"use client";
import { Pencil, Plus, RefreshCw, Search, X } from "lucide-react";
import { FormEvent, useCallback, useEffect, useState } from "react";
type Supplier={id:string;razaoSocial:string;nomeFantasia?:string|null;documento?:string|null;email?:string|null;telefone?:string|null;contato?:string|null;observacoes?:string|null;ativo:boolean};
type Form={razaoSocial:string;nomeFantasia:string;documento:string;email:string;telefone:string;contato:string;observacoes:string;ativo:boolean};const empty:Form={razaoSocial:"",nomeFantasia:"",documento:"",email:"",telefone:"",contato:"",observacoes:"",ativo:true};
export function PurchasesSuppliers({canManage}:{canManage:boolean}){const[data,setData]=useState<Supplier[]>([]);const[search,setSearch]=useState("");const[active,setActive]=useState("");const[form,setForm]=useState<Form>(empty);const[editing,setEditing]=useState<string|null>(null);const[modal,setModal]=useState(false);const[loading,setLoading]=useState(true);const[saving,setSaving]=useState(false);const[error,setError]=useState("");
 const load=useCallback(async()=>{setLoading(true);const q=new URLSearchParams();if(search.trim())q.set("busca",search.trim());if(active)q.set("ativo",active);try{const r=await fetch(`/api/compras/fornecedores?${q}`,{cache:"no-store"});const p:unknown=await r.json();if(!r.ok)throw new Error(typeof p==="object"&&p&&"message" in p?String(p.message):"Falha ao carregar fornecedores");setData(p as Supplier[])}catch(e){setError(e instanceof Error?e.message:"Falha ao carregar fornecedores")}finally{setLoading(false)}},[search,active]);useEffect(()=>{const t=window.setTimeout(()=>void load(),search?350:0);return()=>window.clearTimeout(t)},[load,search,active]);
 function open(s?:Supplier){setEditing(s?.id??null);setForm(s?{razaoSocial:s.razaoSocial,nomeFantasia:s.nomeFantasia??"",documento:s.documento??"",email:s.email??"",telefone:s.telefone??"",contato:s.contato??"",observacoes:s.observacoes??"",ativo:s.ativo}:empty);setError("");setModal(true)}
 async function submit(e:FormEvent){e.preventDefault();setSaving(true);setError("");try{const r=await fetch(editing?`/api/compras/fornecedores/${editing}`:"/api/compras/fornecedores",{method:editing?"PATCH":"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(form)});const p:unknown=await r.json();if(!r.ok)throw new Error(typeof p==="object"&&p&&"message" in p?String(p.message):"Falha ao salvar fornecedor");setModal(false);await load()}catch(e2){setError(e2 instanceof Error?e2.message:"Falha ao salvar fornecedor")}finally{setSaving(false)}}
 return <main className="mx-auto max-w-[1500px] space-y-5"><header className="flex flex-col gap-4 sm:flex-row sm:items-end sm:justify-between"><div><p className="font-semibold text-red-600">Compras</p><h1 className="text-3xl font-bold">Fornecedores</h1><p className="text-sm text-slate-500">Cadastro e contatos dos parceiros de fornecimento.</p></div>{canManage&&<button onClick={()=>open()} className="inline-flex items-center gap-2 rounded-xl bg-red-600 px-4 py-2.5 font-semibold text-white"><Plus/>Novo fornecedor</button>}</header><section className="grid gap-3 rounded-2xl border bg-white p-4 md:grid-cols-[1fr_220px_auto] dark:border-slate-800 dark:bg-slate-950"><label className="relative"><Search className="absolute left-3 top-3 h-4 w-4 text-slate-400"/><input value={search} onChange={e=>setSearch(e.target.value)} placeholder="Razão social, fantasia ou documento" className="w-full rounded-xl border bg-transparent py-2.5 pl-10 pr-3"/></label><select value={active} onChange={e=>setActive(e.target.value)} className="rounded-xl border bg-transparent px-3"><option value="">Todos</option><option value="true">Ativos</option><option value="false">Inativos</option></select><button onClick={()=>void load()} className="rounded-xl border p-2.5"><RefreshCw className={loading?"animate-spin":""}/></button></section>{error&&!modal&&<div role="alert" className="rounded-xl bg-red-50 p-4 text-red-700">{error}</div>}<section className="overflow-hidden rounded-2xl border bg-white dark:border-slate-800 dark:bg-slate-950"><div className="overflow-x-auto"><table className="min-w-full text-sm"><thead className="bg-slate-50 text-left dark:bg-slate-900"><tr>{["Fornecedor","Documento","Contato","E-mail","Telefone","Status",""].map(x=><th key={x} className="px-4 py-3">{x}</th>)}</tr></thead><tbody className="divide-y dark:divide-slate-800">{data.map(s=><tr key={s.id}><td className="px-4 py-3"><b>{s.razaoSocial}</b><small className="block text-slate-500">{s.nomeFantasia}</small></td><td className="px-4 py-3">{s.documento??"—"}</td><td className="px-4 py-3">{s.contato??"—"}</td><td className="px-4 py-3">{s.email??"—"}</td><td className="px-4 py-3">{s.telefone??"—"}</td><td className="px-4 py-3">{s.ativo?"Ativo":"Inativo"}</td><td className="px-4 py-3">{canManage&&<button onClick={()=>open(s)} aria-label={`Editar ${s.razaoSocial}`}><Pencil/></button>}</td></tr>)}</tbody></table></div></section>{modal&&<div className="fixed inset-0 z-50 grid place-items-center bg-black/60 p-4"><form onSubmit={submit} className="max-h-[90vh] w-full max-w-3xl overflow-y-auto rounded-2xl bg-white p-6 shadow-2xl dark:bg-slate-950"><div className="flex justify-between"><h2 className="text-xl font-bold">{editing?"Editar":"Novo"} fornecedor</h2><button type="button" onClick={()=>setModal(false)}><X/></button></div><div className="mt-5 grid gap-4 sm:grid-cols-2">{([['razaoSocial','Razão social'],['nomeFantasia','Nome fantasia'],['documento','CPF/CNPJ'],['email','E-mail'],['telefone','Telefone'],['contato','Contato']] as const).map(([key,label])=><label key={key} className="text-sm font-semibold">{label}<input required={key==='razaoSocial'} value={form[key]} onChange={e=>setForm(v=>({...v,[key]:e.target.value}))} className="mt-2 w-full rounded-xl border bg-transparent px-3 py-2.5"/></label>)}</div><label className="mt-4 block text-sm font-semibold">Observações<textarea value={form.observacoes} onChange={e=>setForm(v=>({...v,observacoes:e.target.value}))} className="mt-2 min-h-24 w-full rounded-xl border bg-transparent p-3"/></label>{editing&&<label className="mt-4 flex gap-2"><input type="checkbox" checked={form.ativo} onChange={e=>setForm(v=>({...v,ativo:e.target.checked}))}/>Fornecedor ativo</label>}{error&&<p role="alert" className="mt-4 rounded-xl bg-red-50 p-3 text-red-700">{error}</p>}<div className="mt-6 flex justify-end gap-3"><button type="button" onClick={()=>setModal(false)} className="rounded-xl border px-4 py-2.5">Cancelar</button><button disabled={saving} className="rounded-xl bg-red-600 px-5 py-2.5 font-semibold text-white disabled:opacity-50">{saving?"Salvando...":"Salvar"}</button></div></form></div>}</main>}
